import json, sys
from pathlib import Path
import torch
from threadpoolctl import threadpool_limits
from coco_baselines.storage import identity
from coco_coordinated import run as memory
from coco_ggf import next_experiments as exp

o = json.loads(Path(sys.argv[1]).read_text())
if exp.matched.versions() != o["expected_versions"]:
    raise RuntimeError("Numerical package versions differ from the saved source.")
if not torch.cuda.is_available() or "T4" not in torch.cuda.get_device_name():
    raise RuntimeError("Select Tesla T4.")

torch.set_num_threads(2)
threadpool_limits(2)
torch.use_deterministic_algorithms(True, warn_only=True)

ctx = exp.prepare(
    o["paths"], o["output"], o["local"], o["cache_local"],
    o["source_sha"], o["previous_output"], o["previous_test_output"]
)
if ctx["store"].run_id != "95fbab1d48bff58545543e390b89e28c87c8cc8612db4fc25e9759489407befb":
    raise ValueError("Wrong destination run.")

# Verify all six completed 5D endpoints without training.
exp.verify_freeze(ctx, "width5")
source = ctx["sources"]["previous"]
if source.run_id != exp.PREVIOUS_RUN:
    raise ValueError("Wrong saved continuation source.")
summary = memory.required(source, "experiment_complete")
if not summary.get("complete"):
    raise ValueError("Saved continuation evaluation is incomplete.")

pending = []
for seed in exp.SEEDS:
    for arm in ["cap040", "vanilla4"]:
        row = exp.root_for(ctx, seed, arm)
        tag = f"s{seed}_{arm}"
        saved = memory.required(source, "audit_" + tag)
        compact = memory.required(source, "compact_" + tag)

        expected = exp.base.report_signature(row, ctx["test_stamp"], ctx["cfg"])
        if saved["identity"] != expected:
            raise ValueError("Audit model/readout/test identity differs: " + tag)
        exp.base.check_report(saved["report"], row, ctx["cfg"])

        entries = [
            r for r in summary["models"]
            if (r["seed"], r["arm"]) == (seed, arm)
        ]
        if len(entries) != 1 or identity(entries[0]) != identity(saved["report"]):
            raise ValueError("Saved summary and audit disagree: " + tag)
        if (
            compact["image_ids"] != ctx["test_ids"]
            or compact["category_indices"] != ctx["cfg"]["category_indices"]
        ):
            raise ValueError("Saved compact audit cohort differs: " + tag)

        for prefix, value in [("audit_", saved), ("compact_", compact)]:
            key = prefix + tag
            old = ctx["store"].load(key)
            if old is not None:
                if identity(exp.engine.state_identity(old)) != identity(exp.engine.state_identity(value)):
                    raise ValueError("Existing destination audit differs: " + key)
            pending.append((key, value, exp.matched.source_key_stamp(source, key)))

# Validate everything before copying any recovered audits.
exp.matched.assert_sources(ctx)
for key, value, stamp in pending:
    if ctx["store"].load(key) is None:
        ctx["store"].save(key, value)
    if stamp not in ctx["checkpoint_stamps"]:
        ctx["checkpoint_stamps"].append(stamp)

ctx["store"].write("control_audit_reuse.json", {
    "source_run": source.run_id,
    "restored_keys": [key for key, _, _ in pending],
    "new_gradient_updates": 0,
    "new_inference": False,
})
ctx["store"].write("source_checkpoint_hashes.json", ctx["checkpoint_stamps"])
ctx["store"].write("recovery/recover_controls_source.json", {
    "code": Path(__file__).read_text()
})
exp.matched.assert_sources(ctx)
print("Saved 4D control audits restored. All trained checkpoints are unchanged.", flush=True)
